"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[7654],{911(e){e.exports=JSON.parse('{"tag":{"label":"Foundations","permalink":"/concepts/tags/foundations","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"principles-of-algorithmics/algorithmic-thinking","title":"Algorithmic Thinking","description":"A programming language is only the vehicle we use to give instructions to a computer. What really decides whether a program is good is the method it follows to solve the problem. Algorithmics is the discipline that studies those methods: how to design them, how to be sure that they are correct, and how to predict how much time and memory they need.","permalink":"/concepts/principles-of-algorithmics/algorithmic-thinking"},{"id":"principles-of-algorithmics/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organized in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","permalink":"/concepts/principles-of-algorithmics/data-structures"}],"unlisted":false}}')}}]);